preConditionHook:
// THE SESSION SO FAR IS A TRADING-RANGE DAY: the distance travelled since the
// open -- the session's highest high minus its lowest low -- is no more than
// dayRangeFraction of the recent average daily range. Used to permit fades
// and scalps and, negated, to permit with-trend swing entries.
// Direction-agnostic: a day type is not long or short, so both sides are
// identical text.
//
// THE DAY-SCALE SIBLING OF RangeWidthBelowAtrMultiple, kept apart because its
// window is the SESSION rather than a bar count and it therefore needs the
// session machinery: early in a session the window is a handful of bars and
// late in one it is most of the day, which no rangeLookback reproduces. The
// width definition is chosen for the same reason it won at bar scale. It
// beats the two counting definitions in the sources -- T07-33's K reversals
// plus tailed bars in the first N bars and R21-14's four or five reversals in
// the first hour -- both of which need "a reversal" defined before they can
// be coded and both of which only PREDICT the day type rather than measure
// it.
//
// Not OpeningRangeVsAvgDailyRange, which divides the same average daily range
// into the OPENING RANGE's frozen height; this one measures the whole session
// so far and keeps growing.
//
// minSessionBars guards the classification from firing on the first few bars,
// when every session is narrow by construction. dayRangeFraction is a FRESH
// READING, not a book number -- Brooks never quantifies a trading-range day.
//
// AverageDailyRange is INLINED, same text as its own file, per the composites
// decision; adrLookbackDays is this rule's name for its dayLookback and
// maxScanBars is promoted with it. The dayLookback guard WRAPS the date read
// rather than being ANDed with it, because EasyLanguage does not short-circuit
// and the twins must touch the same history. Compared, never divided.
//
// SESSION MODEL, per the standing decision: the twin's date > date[1],
// mirrored as day_of(ctx.Time(0)) > day_of(ctx.Time(1)), the same boundary
// the xxxD family carries. Intraday bars only.
//
// Deepest bar touched: maxScanBars + 1.
if (day_of(ctx.Time(0)) > day_of(ctx.Time(1))) {
    barsIn = 1;
    sessHigh = high[0];
    sessLow = low[0];
} else {
    barsIn = barsIn + 1;
    if (el_gt(high[0], sessHigh)) sessHigh = high[0];
    if (el_lt(low[0], sessLow)) sessLow = low[0];
}
adrSum = 0.0;
adrDays = 0;
dHi = 0.0;
dLo = 0.0;
dOpen = false;
for (int kk = 1; kk <= (int)maxScanBars; ++kk) {
    if (el_lt((double)adrDays, adrLookbackDays)) {
        if (day_of(ctx.Time(kk)) != day_of(ctx.Time(0))) {
            if (!dOpen) {
                dHi = high[kk];
                dLo = low[kk];
                dOpen = true;
            } else {
                if (el_gt(high[kk], dHi)) dHi = high[kk];
                if (el_lt(low[kk], dLo)) dLo = low[kk];
            }
            if (day_of(ctx.Time(kk + 1)) != day_of(ctx.Time(kk))) {
                adrSum = adrSum + (dHi - dLo);
                adrDays = adrDays + 1;
                dOpen = false;
            }
        }
    }
}
adrReady = el_ge((double)adrDays, adrLookbackDays);
if (adrReady) {
    adr = adrSum / adrLookbackDays;
} else {
    adr = 0.0;
}
rangeDay = el_ge((double)barsIn, minSessionBars) && adrReady && el_le(sessHigh - sessLow, dayRangeFraction * adr);
